# simpler direct implementation using verified geometry: stamp fliplr of source into empty block
def f(grid):
    g=np.array(grid); H,W=g.shape
    rs=[i for i in range(H) if len(set(g[i]))==1]; cs=[j for j in range(W) if len(set(g[:,j]))==1]
    def bands(seps,n):
        bs=[]; s=0
        for x in seps:
            if x>s: bs.append((s,x-1))
            s=x+1
        bs.append((s,n-1))
        return bs
    rb=bands(rs,H); cb=bands(cs,W)
    sep=int(g[rs[0],cs[0]]) if rs and cs else int(g[0,0])
    O=g.copy()
    for a,(r0,r1) in enumerate(rb):
        for b,(c0,c1) in enumerate(cb):
            S=B[(a,b)]=g[r0:r1+1,c0:c1+1]
            if not (S!=sep & S!=0).any() and (S==0).all():  # empty block (may be partial size)
                for da,db in ((0,-1),(0,1)):
                    sb = a+da,b+db
                    if 0<=sb[0]<len(rb) and 0<=sb[1]<len(cb):
                        SS=g[rb[sb[0]][0]:rb[sb[0]][1]+1, cb[sb[1]][0]:cb[sb[1]][1]+1]
                        nz=(SS!=sep)&(SS!=0)
                        if nz.any():
                            F=SS[:,::-1]
                            O[r0:r1+1, c0:c1+1]=F
    return O
